/* Bit-exact C model for dd4_ks_norc_nw (generated by mk_c_impl.py).
 * Construction: 4r SPN, rk_r = rotl64(k, 13u * (unsigned)(r + 1)) ^ RC[r] */
#include <stdint.h>

static const uint8_t SBOX_R0[16] = {0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14};
static const uint8_t SBOX_R1[16] = {0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14};
static const uint8_t SBOX_R2[16] = {0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14};
static const uint8_t SBOX_R3[16] = {0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14};

static const uint8_t PBOX[64] = {1, 20, 39, 58, 13, 32, 51, 6, 25, 44, 63, 18, 37, 56, 11, 30, 49, 4, 23, 42, 61, 16, 35, 54, 9, 28, 47, 2, 21, 40, 59, 14, 33, 52, 7, 26, 45, 0, 19, 38, 57, 12, 31, 50, 5, 24, 43, 62, 17, 36, 55, 10, 29, 48, 3, 22, 41, 60, 15, 34, 53, 8, 27, 46};

static const uint64_t RC[4] = {0x0000000000000000ULL, 0x0000000000000000ULL, 0x0000000000000000ULL, 0x0000000000000000ULL};

static uint64_t rotl64(uint64_t x, unsigned r) {
    r &= 63;
    return r ? (x << r) | (x >> (64 - r)) : x;
}

uint64_t mix_hash(uint64_t v, uint64_t k) {
    uint64_t x = v;
    for (int r = 0; r < 4; r++) {
        uint64_t rk = (rotl64(k, 13u * (unsigned)(r + 1))) ^ RC[r];
        uint64_t t = x ^ rk;
        /* S-box (per-round table) */
        uint64_t y = 0;
        for (int n = 0; n < 16; n++) {
            uint8_t nib;
            switch (r) {
                case 0: nib = SBOX_R0[(t >> (4*n)) & 0xF]; break;
                case 1: nib = SBOX_R1[(t >> (4*n)) & 0xF]; break;
                case 2: nib = SBOX_R2[(t >> (4*n)) & 0xF]; break;
                case 3: nib = SBOX_R3[(t >> (4*n)) & 0xF]; break;
                default: nib = 0; break;
            }
            y |= (uint64_t)nib << (4*n);
        }
        /* P-box */
        uint64_t z = 0;
        for (int i = 0; i < 64; i++)
            z |= ((y >> i) & 1ULL) << PBOX[i];
        /* LIN: per-round rotation pair */
        switch (r) {
            case 0: x = z ^ rotl64(z, 5) ^ rotl64(z, 13); break;
            case 1: x = z ^ rotl64(z, 5) ^ rotl64(z, 13); break;
            case 2: x = z ^ rotl64(z, 5) ^ rotl64(z, 13); break;
            case 3: x = z ^ rotl64(z, 5) ^ rotl64(z, 13); break;
            default: x = z; break;
        }
    }
    return x;
}
